        Dhikr(text: 'لَا إلَه إلّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلُّ شَيْءِ قَدِيرِ.', count: 100, description: 'فضلها: كانت له عدل عشر رقاب، وكتبت له مئة حسنة، ومحيت عنه مئة سيئة، وكانت له حرزا من الشيطان.'),
        Dhikr(text: 'لا حَوْلَ وَلا قُوَّةَ إِلا بِاللَّهِ', count: 100, description: 'فضلها: كنز من كنوز الجنة.'),
        Dhikr(text: 'الْحَمْدُ للّهِ رَبِّ الْعَالَمِينَ', count: 100, description: 'فضلها: تملأ ميزان العبد بالحسنات.'),
        Dhikr(text: 'الْلَّهُم صَلِّ وَسَلِم وَبَارِك عَلَى سَيِّدِنَا مُحَمَّد', count: 100, description: 'فضلها: من صلى على حين يصبح وحين يمسى ادركته شفاعتى يوم القيامة.'),
