        Dhikr(text: 'لَا إِلَهَ إِلَّا اللَّهُ', count: 100, description: 'فضلها: أفضل الذكر لا إله إلاّ الله.'),
        Dhikr(text: 'الْلَّهُ أَكْبَرُ', count: 100, description: 'فضلها: من قال الله أكبر كتبت له عشرون حسنة وحطت عنه عشرون سيئة. الله أكبر من كل شيء.'),
        Dhikr(text: 'سُبْحَانَ اللَّهِ ، وَالْحَمْدُ لِلَّهِ ، وَلا إِلَهَ إِلا اللَّهُ ، وَاللَّهُ أَكْبَرُ ، اللَّهُمَّ اغْفِرْ لِي ، اللَّهُمَّ ارْحَمْنِي ، اللَّهُمَّ ارْزُقْنِي.', count: 100, description: 'فضلها: خير الدنيا والآخرة'),
